package com.graduation.lostfound.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(LostFoundPostRepository posts, com.graduation.lostfound.auth.SeedAuthBridge auth){return args->{if(posts.count()==0){var x=new LostFoundPost();x.setType("FOUND");x.setTitle("图书馆二楼捡到黑色耳机盒");x.setCategory("数码");x.setLocation("图书馆二楼自习区");x.setEventTime(java.time.LocalDateTime.now().minusHours(4));x.setDescription("盒盖内侧有一处小划痕，请说明品牌和耳机颜色认领");x.setContact("服务台");x.setOwnerUserId(auth.currentUserSeedId());x.setStatus("OPEN");posts.save(x);}};}}
